class Solution{public boolean isInterleave(String a,String b,String c){if(c.length()!=a.length()+b.length())return false;boolean[]d=new boolean[b.length()+1];d[0]=true;for(int j=1;j<=b.length();j++)d[j]=d[j-1]&&b.charAt(j-1)==c.charAt(j-1);for(int i=1;i<=a.length();i++){d[0]=d[0]&&a.charAt(i-1)==c.charAt(i-1);for(int j=1;j<=b.length();j++)d[j]=d[j]&&a.charAt(i-1)==c.charAt(i+j-1)||d[j-1]&&b.charAt(j-1)==c.charAt(i+j-1);}return d[b.length()];}}
